function remplirMatrice(grille, x, y, nouvelleValeur) {
    const ancienneValeur = grille[y][x];
    if (ancienneValeur === nouvelleValeur) {
        return grille;
    }

    const lignes = grille.length;
    const colonnes = grille[0].length;
    const file = [[x, y]];

    while (file.length > 0) {
        const [cx, cy] = file.shift();

        if (cx < 0 || cx >= colonnes || cy < 0 || cy >= lignes) {
            continue;
        }

        if (grille[cy][cx] !== ancienneValeur) {
            continue;
        }

        grille[cy][cx] = nouvelleValeur;
        file.push([cx - 1, cy]);
