/**
 * Calcule la médiane d'un tableau de nombres.
 * Pour une longueur impaire : valeur centrale.
 * Pour une longueur paire : moyenne des deux valeurs centrales.
 * @param {number[]} tab Le tableau de nombres.
 * @returns {number} La médiane du tableau.
 */
function mediane(tab) {
    if (tab.length === 0) return 0; // Gère le cas d'un tableau vide

    // 1. Trier le tableau numériquement
    const sortedTab = [...tab].sort((a, b) => a - b);
    const n = sortedTab.length;
    const middleIndex = Math.floor(n / 2);

    if (n % 2 === 1) {
        // Longueur impaire : retourne l'élément au milieu
        return sortedTab[middleIndex];
    } else {
        // Longueur paire : moyenne des deux éléments centraux
        const lowerMiddle = sortedTab[middleIndex - 1];
        const upperMiddle = sortedTab[middleIndex];
        return (lowerMiddle + upperMiddle) / 2;
    }
}
