 * Si la longueur est impaire, c'est l'élément du milieu. 
 * Si la longueur est paire, c'est la moyenne des deux éléments du milieu.
 * @param {number[]} tab Le tableau de nombres.
 * @returns {number|undefined} La médiane ou undefined si le tableau est vide.
 */
function mediane(tab) {
    if (!tab || tab.length === 0) return undefined;

    // Créer une copie et trier numériquement
    const sortedTab = [...tab].sort((a, b) => a - b);
    const length = sortedTab.length;
    const middleIndex = Math.floor(length / 2);

    if (length % 2 === 1) {
        // Longueur impaire : retour de l'élément central
        return sortedTab[middleIndex];
    } else {
        // Longueur paire : moyenne des deux éléments centraux
        const mid1 = sortedTab[middleIndex - 1];
        const mid2 = sortedTab[middleIndex];
        return (mid1 + mid2) / 2;
