/**
 * Calcule x à la puissance n en utilisant l'exponentiation rapide (Exponentiation by Squaring).
 * @param {number} x - La base.
 * @param {number} n - L'exposant (n >= 0).
 * @returns {number} Le résultat de x^n.
 */
function exponentiationRapide(x, n) {
    if (n < 0) {
        throw new Error("L'exposant doit être non négatif.");
    }
    if (n === 0) {
        return 1;
    }
    if (n === 1) {
        return x;
    }

    let resultat = 1;
    let baseCourante = x;
    let exposant = n;

    // Approche itérative basée sur les bits de l'exposant
    while (exposant > 0) {
        // Si le bit de poids faible est 1 (n est impair)
        if (exposant % 2 === 1) {
            resultat *= baseCourante;
        }
        // Élever la base au carré pour l'itération suivante
        baseCourante *= baseCourante;
        // Passer à la moitié de l'exposant (décalage à droite)
        exposant = Math.floor(exposant / 2);
    }

    return resultat;
}
