/**
 * Trouve la somme maximale d'un sous-tableau contigu en utilisant l'algorithme de Kadane.
 * @param {Array<number>} tab - Le tableau d'entrée contenant des nombres (positifs ou négatifs).
 * @returns {number} La somme maximale du sous-tableau contigu.
 */
function sousTableauMax(tab) {
    if (!tab || tab.length === 0) {
        return 0; // Ou -Infinity, selon la convention pour un tableau vide. 0 est souvent acceptable si on suppose des sommes non négatives possibles.
    }

    // Initialisation : le maximum global et le maximum courant sont initialisés à la première valeur.
    let maxGlobal = tab[0];
    let maxCourant = tab[0];

    for (let i = 1; i < tab.length; i++) {
        const element = tab[i];

        // Le nouveau maximum courant est soit l'élément lui-même, soit l'élément ajouté au maximum précédent.
        maxCourant = Math.max(element, maxCourant + element);

        // Mettre à jour le maximum global si le maximum courant est plus grand.
        maxGlobal = Math.max(maxGlobal, maxCourant);
    }

    return maxGlobal;
}
