/**
 * Extrait un code d'accès spécifique (CODE_ACCES: XXXXX) à partir d'un document technique long.
 * Le code est composé de lettres majuscules et de chiffres, et se termine par un point ou un espace.
 * @param {string} document - Le texte du document.
 * @returns {string|null} Le code extrait (ex: "8X42A"), ou null si non trouvé.
 */
function extraireCode(document) {
    if (!document || typeof document !== 'string') {
        return null;
    }

    // Regex explanation:
    // CODE_ACCES:\s* : Cherche la chaîne littérale suivie d'espaces optionnels.
    // ([A-Z0-9]+)   : Capture un ou plusieurs caractères majuscules ou chiffres (le code). C'est le groupe de capture 1.
    // (?=[.\s]|$)  : Lookahead positif : assure que ce qui suit est soit un point, soit un espace, soit la fin de la chaîne ($), sans l'inclure dans la correspondance.
    const regex = /CODE_ACCES:\s*([A-Z0-9]+)(?=[.\s]|$)/;

    const match = document.match(regex);

    // Si une correspondance est trouvée, le code est dans le premier groupe de capture (index 1).
    if (match && match[1]) {
        return match[1];
    } else {
        return null;
    }
}
