 * @param {number[]} tab - Le tableau d'entrée.
 * @returns {number} La longueur du LIS.
 */
function plusLongueSousSuiteCroissante(tab) {
    if (!tab || tab.length === 0) {
        return 0;
    }

    // 'tails' stocke le dernier élément de toutes les sous-suites croissantes de longueur i+1 trouvées jusqu'à présent.
    // Il est maintenu trié.
    const tails = [];

