     * Fonction d'implémentation du tri binaire (Binary Search).
     * Trouve l'index du premier élément dans 'tails' qui est supérieur ou égal à la valeur donnée.
     */
    function binarySearch(arr, target) {
        let left = 0;
        let right = arr.length - 1;
        let resultIndex = arr.length; // Par défaut: si le target est plus grand que tous les éléments

        while (left <= right) {
            const mid = Math.floor((left + right) / 2);
            if (arr[mid] >= target) {
                resultIndex = mid;
                right = mid - 1; // Essayer de trouver un index encore plus petit
            } else {
                left = mid + 1;
            }
        }
        return resultIndex;
    }

    for (const num of tab) {
        // Trouver l'index où 'num' peut remplacer le dernier élément d'une sous-suite existante.
        const i = binarySearch(tails, num);

        if (i === tails.length) {
            // Si 'num' est plus grand que tous les éléments dans 'tails', il prolonge la LIS actuelle.
            tails.push(num);
        } else {
            // Sinon, nous avons trouvé une sous-suite de longueur i+1 dont le dernier élément (tails[i]) 
            // peut être remplacé par un plus petit nombre ('num'), ce qui ouvre la possibilité d'une LIS plus longue plus tard.
            tails[i] = num;
        }
    }

    // La longueur du tableau 'tails' est la longueur de la LIS.
    return tails.length;
