      [heap[parent(i)], heap[i]] = [heap[i], heap[parent(i)]];
      i = parent(i);
    }
  }

  function bubbleDown(i) {
    let smallest = i;
    const l = left(i);
    const r = right(i);
    if (l < heap.length && heap[l].priorite < heap[smallest].priorite) smallest = l;
    if (r < heap.length && heap[r].priorite < heap[smallest].priorite) smallest = r;
    if (smallest !== i) {
      [heap[i], heap[smallest]] = [heap[smallest], heap[i]];
      bubbleDown(smallest);
    }
