async function executerEnPool(taches, concurrence) {
  const results = new Array(taches.length);
  let index = 0;

  async function next() {
    const i = index++;
    if (i >= taches.length) return;
    try {
      results[i] = await taches[i]();
    } catch (e) {
      results[i] = e;
    }
    await next();
  }

  const workers = [];
  const limite = Math.min(concurrence, taches.length);
  for (let w = 0; w < limite; w++) {
    workers.push(next());
  }
  await Promise.all(workers);
  return results;
}
```

