function creerCircuitBreaker(fn, seuil, delaiResetMs) {
  let etat = 'ferme';
  let echecsConsecutifs = 0;
  let prochaineTentative = 0;

  return async function(...args) {
    if (etat === 'ouvert') {
      if (Date.now() < prochaineTentative) {
        throw new Error('Circuit breaker ouvert');
      }
      etat = 'demi-ouvert';
    }

    try {
      const resultat = await fn.apply(this, args);
      echecsConsecutifs = 0;
      if (etat === 'demi-ouvert') {
        etat = 'ferme';
      }
      return resultat;
    } catch (erreur) {
      echecsConsecutifs++;
      if (echecsConsecutifs >= seuil) {
        etat = 'ouvert';
        prochaineTentative = Date.now() + delaiResetMs;
      }
      throw erreur;
    }
  };
}
