  let derniereErreur;
  for (let tentative = 1; tentative <= maxTentatives; tentative++) {
    try {
      return await operation();
    } catch (erreur) {
      derniereErreur = erreur;
      if (tentative < maxTentatives) {
        const delai = Math.pow(2, tentative) * 100;
