 * Utilise l'algorithme du Tri par Sélection (Selection Sort).
 * @param {number[]} arr Le tableau à trier.
 * @returns {number[]} Le tableau trié.
 */
function trier_tableau(arr) {
    const n = arr.length;

    // Créer une copie pour ne pas modifier le tableau original si ce n'est pas souhaité, 
    // bien que l'exercice implique souvent de retourner la structure modifiée.
    const sortedArr = [...arr]; 

    for (let i = 0; i < n - 1; i++) {
        // Trouver l'indice du minimum dans le reste du tableau non trié
        let minIndex = i;
        for (let j = i + 1; j < n; j++) {
            if (sortedArr[j] < sortedArr[minIndex]) {
                minIndex = j;
            }
        }

        // Échanger l'élément minimum trouvé avec l'élément à la position i
