 * Time Complexity: O(N log N) due to sorting.
 * @param {number[][]} tab An array of intervals [[start, end], ...].
 * @returns {number[][]} The merged and sorted array of non-overlapping intervals.
 */
function fusionnerIntervalles(tab) {
    if (!tab || tab.length === 0) {
        return [];
    }

    // 1. Sort the intervals based on their start time (the first element).
    // This is crucial for the linear scan approach.
    const sortedIntervals = [...tab].sort((a, b) => a[0] - b[0]);

    const merged = [];
    let currentInterval = sortedIntervals[0];
    merged.push(currentInterval);

    for (let i = 1; i < sortedIntervals.length; i++) {
        const nextInterval = sortedIntervals[i];
        const lastMerged = merged[merged.length - 1];

        // Check for overlap: Overlap occurs if the current interval starts before or at the end of the last merged interval.
