/**
 * Counts the number of set bits (1s) in the binary representation of a non-negative integer n.
 * Uses Brian Kernighan's Algorithm for efficiency.
 * @param {number} n The non-negative integer.
 * @returns {number} The count of set bits.
 */
function nombreDeBits1(n) {
    if (typeof n !== 'number' || n < 0) {
        throw new Error("Input must be a non-negative number.");
    }

    let count = 0;
    let tempN = n;

    // Brian Kernighan's Algorithm: n & (n - 1) clears the least significant set bit.
    while (tempN > 0) {
        tempN &= (tempN - 1);
        count++;
    }

