}

/**
 * Finds the median of two sorted arrays combined in O(log(min(m, n))) time.
 * This implementation uses a recursive binary search approach to find the correct partition.
 * @param {number[]} a The first sorted array.
 * @param {number[]} b The second sorted array.
 * @returns {number} The median value.
 */
function medianeDeuxTries(a, b) {
    // Ensure A is the smaller array to minimize search space (O(log(min(m, n))))
    if (a.length > b.length) {
        return medianeDeuxTries(b, a);
    }

    const m = a.length;
    const n = b.length;
    const totalLength = m + n;
    // The target partition size for the left half (k elements)
    const halfLen = Math.floor((totalLength + 1) / 2);

    let low = 0;
    let high = m; // Search space is on array A's partition point

    while (low <= high) {
        // Partition point for A: i elements in the left half of A
        const i = Math.floor((low + high) / 2);
        // Required partition point for B: j elements in the left half of B
        const j = halfLen - i;

        // Define boundary values (handling edge cases where partitions are empty)
        const aLeftMax = (i === 0) ? Number.NEGATIVE_INFINITY : a[i - 1];
        const aRightMin = (i === m) ? Number.POSITIVE_INFINITY : a[i];

        const bLeftMax = (j === 0) ? Number.NEGATIVE_INFINITY : b[j - 1];
        const bRightMin = (j === n) ? Number.POSITIVE_INFINITY : b[j];

        // Check if the partition is correct:
        // 1. Max of left half <= Min of right half for both arrays.
        if (aLeftMax <= bRightMin && bLeftMax <= aRightMin) {
            // Found the perfect split!
            const maxLeft = Math.max(aLeftMax, bLeftMax);

            if (totalLength % 2 === 1) {
                // Odd total length: Median is the largest element in the left half
                return maxLeft;
            } else {
                // Even total length: Median is the average of the two middle elements
                const minRight = Math.min(aRightMin, bRightMin);
                return (maxLeft + minRight) / 2.0;
            }
        } else if (aLeftMax > bRightMin) {
            // A's left max is too large; we need to move the partition in A to the left.
            high = i - 1;
        } else { // bLeftMax > aRightMin
            // B's left max is too large (meaning A's partition 'i' was too small); move right.
            low = i + 1;
        }
    }

    // Should theoretically never be reached if inputs are sorted arrays.
    return 0; 
}

/**
 * Finds the length of the Longest Strictly Increasing Subsequence (LIS) in an array.
 * Uses the optimized O(N log N) algorithm involving binary search.
 * @param {number[]} tab The input array.
 * @returns {number} The length of the LIS.
 */
function plusLongueSousSuiteCroissante(tab) {
    if (!tab || tab.length === 0) {
        return 0;
    }

    // 'tails' stores the smallest tail element for all increasing subsequences 
    // found so far with length i+1 at index i. This array is always sorted.
    let tails = [];

    /**
     * Binary search helper function to find the insertion point (the ceiling).
     * Finds the smallest element in 'tails' that is >= target.
     * @param {number} target The value to search for.
     * @returns {number} The index where the replacement should occur, or tails.length if all elements are smaller.
     */
    const binarySearch = (target) => {
        let left = 0;
        let right = tails.length - 1;
        let resultIndex = tails.length; // Default: append to end

        while (left <= right) {
            const mid = Math.floor((left + right) / 2);
            if (tails[mid] >= target) {
                // Potential candidate found, try for an even smaller index
                resultIndex = mid;
                right = mid - 1;
            } else {
                // tails[mid] < target, must search in the right half
                left = mid + 1;
            }
        }
        return resultIndex;
    };

    for (const num of tab) {
        // Find the index 'i' where we can replace an existing tail element.
        let i = binarySearch(num);

        if (i === tails.length) {
            // Case 1: Num is larger than all current tails. Extend the LIS length by 1.
            tails.push(num);
        } else {
            // Case 2: Found a tail element at index 'i' that can be replaced by a smaller number (num).
            // This ensures that for subsequences of length i+1, we maintain the smallest possible tail.
            tails[i] = num;
        }
    }

    // The length of the 'tails' array is the length of the LIS.
    return tails.length;
}

