  if (m === 0 && n === 0) return 0 / 2; // Cas extrême (double tableau vide)
  let i = j = 0;
  const merged = new Array(m + n);
  let k = 0; // Index dans merged
  while (i < m && j < n) {
    if (a[i] <= b[j]) {
      merged[k++] = a[i++];
    } else {
      merged[k++] = b[j++];
    }
  }
  // Compléter avec les éléments restants de a ou b
  while (i < m) merged[k++] = a[i++];
  while (j < n) merged[k++] = b[j++];
  const total = k;
  if (total % 2 === 1) {
    return merged[Math.floor(total / 2)]; // Médiane impaire : élément central
  } else {
    const midIndex = total / 2;
    return (merged[midIndex - 1] + merged[midIndex]) / 2; // Médiane paire : moyenne des deux mises en centre
  }
}
