function motsUniques(s) {
    const mots = s.split(/\s+/);
    const set = new Set();
    for (let i = 0; i < mots.length; i++) {
        if (mots[i].length > 0) {
            set.add(mots[i]);
        }
    }
    return set.size;
}
```

### algo_difficile_1
```javascript
function aplatirTableau(tab) {
    const resultat = [];
    for (let i = 0; i < tab.length; i++) {
        if (Array.isArray(tab[i])) {
            for (let j = 0; j < tab[i].length; j++) {
                resultat.push(tab[i][j]);
            }
        }
    }
    return resultat;
}
```

### algo_defi
```javascript
function rotationDroite(tab, k) {
    if (!tab || tab.length === 0) return [];
    const n = tab.length;
    k = k % n;
    if (k === 0) return [...tab];
    const resultat = new Array(n);
    for (let i = 0; i < n; i++) {
        resultat[(i + k) % n] = tab[i];
    }
    return resultat;
}
