function median(tab) {
  const sortedTab = [...tab].sort((a, b) => a - b);
  const len = sortedTab.length;
  if (len % 2 === 0) {
    return (sortedTab[len / 2 - 1] + sortedTab[len / 2]) / 2;
  } else {
    return sortedTab[Math.floor(len / 2)];
  }
}

