function fusionnerIntervalles(tab) {
  if (!tab || tab.length === 0) return [];
  const merged = [];
  let i = 0;
  let j = 0;

  while (i < tab.length && j < tab[i].length) {
    if (tab[i][0] <= tab[j][0]) {
      merged.push(tab[i]);
      i++;
    } else {
      merged.push(tab[j]);
      j++;
    }
  }

  while (i < tab.length) {
    merged.push(tab[i]);
    i++;
  }

  return merged;
}
```

### algo_facile_2
```javascript
function prefixeCommun(tab) {
  if (!tab || tab.length === 0) return [];
  let longestCommonPrefix = "";
  for (let i = 0; i < tab[0].length; i++) {
    let char = tab[0][i];
    let isCommon = true;
    for (let j = 1; j < tab.length; j++) {
      if (tab[j][i] !== char) {
        isCommon = false;
        break;
      }
    }
    if (isCommon) {
      longestCommonPrefix += char;
    } else {
      break;
    }
  }

  return longestCommonPrefix;
}
```

