### algo_difficile_1
```javascript
function medianDeuxTries(a, b) {
  const sorted = [...[a, b]].sort((x, y) => x - y);
  const mid = Math.floor(sorted.length / 2);

  if (sorted[mid] > sorted[mid + 1]) {
    return medianDeuxTries(sorted[mid], sorted.slice(0, mid).concat(sorted[mid+1])).toString();
  } else {
    return medianDeuxTries(sorted[mid + 1], a).toString();
  }
}
```

