function exponentiationRapide(x, n) {
    if (n < 0) throw new Error('N doit être positif.');
    let resultat = 1;
    let base = x;

    while (n > 0) {
        if (n % 2 === 1) resultat *= base;
        base *= base;
        n = Math.floor(n / 2);
    }

    return resultat;
}
```

