```javascript
function sousTableauMax(tab) {
    let maxSoFar = -Infinity, currentSum = 0;

    for (const num of tab) {
        currentSum += num;
        maxSoFar = Math.max(maxSoFar, currentSum);
        if (currentSum < 0) currentSum = 0;
    }

    return maxSoFar;
}
