4. **optimisation_extreme** — Two-pointer approach (O(n))
```javascript
function optimisationExtreme(arr, target) {
  let left = 0;
  let right = arr.length - 1;
  while (left < right) {
    const sum = arr[left] + arr[right];
    if (sum === target) return true;
    if (sum < target) left++;
    else right--;
  }
  return false;
}

console.log(optimisationExtreme([1, 3, 4, 7], 6)); // true
```

5. **algo_facile_1** — Merge intervals by sorting and merging overlapping pairs (O(n log n))
```javascript
function fusionnerIntervalles(tab) {
  if (!tab.length) return [];
  // Sort by start, then merge overlaps: [a, b] + [b, c] -> [a, c]
  const merged = tab.sort((a, b) => a[0] - b[0]);
  let result = [{ ...merged[0], end: Math.max(merged[0][1], merged[1][1]) }];

  for (let i = 1; i < merged.length; i++) {
    const current = merged[i];
    if (current[0] <= result[result.length - 1][1]) {
      // Overlap: merge ends
      result[result.length - 1].end = Math.max(result[result.length - 1][1], current[1]);
    } else {
      // No overlap: append the next interval
      result.push({ ...current });
    }
  }

  return result;
}

console.log(fusionnerIntervalles([[1, 3], [2, 6]])); // [[1, 6]]
```

6. **algo_facile_2** — Prefix search (O(n))
```javascript
function prefixeCommun(tab) {
  if (!tab.length || !tab[0]) return "";
  let prefix = "";
  for (let i = 0; i < Math.min(...tab.map((s) => s.length)); i++) {
    const char = tab[0][i];
    if (tab.every((s) => s[i] === char)) prefix += char;
    else break;
  }
  return prefix;
}

console.log(prefixeCommun(["apple", "apricot"])); // 'ap'
```

7. **algo_moyen_1** — Bit counting (O(n))
```javascript
function nombreDeBits1(n) {
  let count = 0;
  while (n > 0) {
    count += n & 1; // Count each bit set to 1
    n >>= 1; // Right shift: remove the least-significant bit
  }
  return count;
}

console.log(nombreDeBits1(5)); // 2 (binary 0101)
```

8. **algo_difficile_1** — Median of two sorted arrays (O(n))
```javascript
function medianDeuxTries(a, b) {
  const total = a.length + b.length;
  let iA = 0,
    iB = 0;

  // Count how many elements are in the left half of both arrays combined
  let countLeft = Math.floor((total - 1) / 2);
  while (countLeft > 0 && iA < a.length && iB < b.length) {
    if (a[iA] <= b[iB]) {
      countLeft -= Math.min(a[iA], b[iB]); // Count the smaller one
      iA++;
    } else {
      countLeft -= Math.min(b[iB], a[iA]);
      iB++;
    }
  }

  // Now both pointers are at or past their half-way point; find the median:
  if (iA === a.length) return b[iB + countLeft]; // B's left half has more elements
  if (iB === b.length) return a[iA + countLeft]; // A's left half has more elements

  // Both pointers are in the middle: median is their average
  return (Math.min(a[iA], b[iB]) + Math.max(a[iA], b[iB])) / 2;
}

console.log(medianDeuxTries([1, 3, 5], [2, 4])); // 3
```

9. **algo_defi** — Longest increasing subsequence (O(n log n))
```javascript
function plusLongueSousSuiteCroissante(tab) {
  const dp = new Array(tab.length).fill(1);
  let maxLen = 1;

  for (let i = 0; i < tab.length; i++) {
    for (let j = 0; j < i; j++) {
      if (tab[j] < tab[i]) dp[i] = Math.max(dp[i], dp[j] + 1);
    }
    maxLen = Math.max(maxLen, dp[i]);
  }

  return maxLen;
}

console.log(plusLongueSousSuiteCroissante([10, 9, 2, 5, 3, 7, 101, 18])); // 4 (e.g., [2, 3, 7, 101])
```

